import {useLayoutEffect} from 'react'

import {useBooleanQueryParam} from '../../../hooks/routes'

function usePipelinesPages() {
  const isEdit = useBooleanQueryParam('edit')
  useLayoutEffect(() => {
    if (isEdit) {
      document.documentElement.classList.add('settings-mode')
      return () => {
        document.documentElement.classList.remove('settings-mode')
      }
    }
    return undefined
  }, [isEdit])
}

export default usePipelinesPages
