import type {FunctionComponent} from 'react'
import {Suspense, useMemo} from 'react'
import {Outlet} from 'react-router'

import Feedback from './components/Feedback/Feedback'
import BannersProvider from './contexts/Banners/BannersContext'
import {pipelinesAppId} from './PipelinesPages.consts'
import usePipelinesPages from './PipelinesPages.hooks'
import {isPipelinesFeedbackFormEnabled} from './utils/featureToggles'

import styles from './PipelinesPages.module.css'

const PipelinesPages: FunctionComponent = () => {
  usePipelinesPages()
  return useMemo(
    () => (
      <BannersProvider>
        <div className={styles.app} id={pipelinesAppId}>
          <Outlet />
        </div>
        {isPipelinesFeedbackFormEnabled ? (
          <Suspense>
            <Feedback />
          </Suspense>
        ) : null}
      </BannersProvider>
    ),
    [],
  )
}

export default PipelinesPages
